    // so we fuzz a uint256 count and an address 'from'. The test constructs an array of addresses
    // all pointing to a Reverter helper to simulate an external callee that always reverts.
    function testFuzz_property(address from, uint256 count) public {
        // keep count small and non-zero but otherwise wide
        uint256 n = bound(count, 1, 16);

        // deploy adversarial helper that always reverts on calls
        Reverter rev = new Reverter();

        // build array of addresses length n pointing to the reverter
