contract ReverterVariant {
    // Fallback will revert if calldata appears to be non-empty selector matching transferFrom
    // but we also use a subtle check: when the call is encoded with an explicit {value:0},
    // some EVM call framing differences can be simulated by testing msg.value (always 0 here)
