        // Revert for any calldata that looks like transferFrom(address,address,uint256)
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (msg.data.length >= 4) {
            bytes4 sig;
            assembly { sig := calldataload(0) }
            if (sig == id) {
                revert("bad");
            }
        }
        // otherwise accept
    }
}

